def sniff_hls_ativo(vercel_url):
    """FAREJADOR: Captura o link HLS atual na página da Vercel"""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Referer': 'https://sinalpublicoetv.vercel.app/'
    }
    try:
        # Acessa a página para capturar o código fonte e os cookies de sessão
        resp = session.get(vercel_url, headers=headers, timeout=10)
        html = resp.text
        
        # 1. Fareja links diretos .m3u8, .txt ou cloudfront no HTML
        match = re.search(r'(https://[^\s\'"]+cloudfront[^\s\'"]+\.(?:m3u8|txt|html)[^\s\'"]*)', html)
        if match: return match.group(1)
            
        # 2. Fareja em Base64 (atob)
        base64_matches = re.findall(r'atob\([\'"]([a-zA-Z0-9+/=]+)[\'"]\)', html)
        for b in base64_matches:
            try:
                decoded = base64.b64decode(b).decode('utf-8')
                if 'http' in decoded and 'cloudfront' in decoded:
                    return decoded
            except: continue

        # 3. Fallback: Gera o link via MD5 do ID do canal
        channel_id = vercel_url.split("id=")[-1].split("&")[0]
        ch_hash = hashlib.md5(channel_id.encode()).hexdigest()
        return f"https://t5r4e3w2q1y0.s21-cloudfront-net.lat/test/{ch_hash}/file.txt"
    except: pass
    return None

@app.route('/')
def index():
    return "Farejador IPTV Ativo!"

@app.route('/lista.m3u')
def get_m3u():
    m3u = "#EXTM3U\n"
    host = request.host_url.rstrip('/')
    for ch in CHANNELS_JSON:
        # O link na lista aponta para o nosso processador dinâmico
        link_proxy = f"{host}/play.m3u8?u={ch['url']}"
        m3u += f'#EXTINF:-1 tvg-logo="{ch["image"]}", {ch["name"]}\n{link_proxy}\n'
    return Response(m3u, mimetype='text/plain')

@app.route('/play.m3u8')
def proxy_handler():
    vercel_url = request.args.get('u')
    if not vercel_url: return "URL ausente", 400

    # FAREJA O LINK REAL NA HORA DO PLAY
    target_url = sniff_hls_ativo(vercel_url)
    if not target_url: return "Link de vídeo não encontrado", 404

    # Headers para burlar o erro 403 Forbidden do Cloudfront
    bypass_headers = {
        'User-Agent': 'Mozilla/5.0',
        'Referer': 'https://t5r4e3w2q1y0-cloudflare-net.vercel.app/',
        'Origin': 'https://t5r4e3w2q1y0-cloudflare-net.vercel.app',
        'X-Forwarded-For': '177.100.100.100'
    }

    try:
        # Puxa o manifesto do vídeo (file.txt / m3u8)
        resp = session.get(target_url, headers=bypass_headers, timeout=15)
        
        # Tenta sem o /test/ se der erro
        if resp.status_code != 200 and "/test/" in target_url:
            target_url = target_url.replace("/test/", "/")
            resp = session.get(target_url, headers=bypass_headers, timeout=15)

        if resp.status_code != 200: return f"Erro 403 no Servidor", 403

        # REESCREVE OS SEGMENTOS PARA PASSAR PELO NOSSO SERVIDOR
        parsed_uri = urlparse(target_url)
        domain_base = f"{parsed_uri.scheme}://{parsed_uri.netloc}"
        path_base = target_url.rsplit('/', 1)[0]
        host = request.host_url.rstrip('/')
        
        lines = resp.text.splitlines()
        new_lines = []
        for line in lines:
            line = line.strip()
            if not line: continue
            
            if not line.startswith("#"):
                # Corrige links relativos
                if line.startswith("http"): full_url = line
                elif line.startswith("/"): full_url = domain_base + line
                else: full_url = path_base + "/" + line
                # Faz o pedaço passar pelo proxy de segmento para injetar os headers
                new_lines.append(f"{host}/segment?u={full_url}")
            else:
                new_lines.append(line)
        
        return Response("\n".join(new_lines), mimetype='application/vnd.apple.mpegurl')
    except Exception as e:
        return str(e), 500

@app.route('/segment')
def proxy_segment():
    target_url = request.args.get('u')
    bypass_headers = {
        'User-Agent': 'Mozilla/5.0',
        'Referer': 'https://t5r4e3w2q1y0-cloudflare-net.vercel.app/'
    }
    try:
        # Entrega o pedaço do vídeo com os cabeçalhos que liberam o sinal
        resp = session.get(target_url, headers=bypass_headers, stream=True, timeout=15)
        return Response(resp.content, content_type=resp.headers.get('Content-Type', 'video/mp2t'))
    except:
        return "Erro no segmento", 500

